/* ---------- Proposal card ---------- */
/* a suggestion posted in the chat: no container; with .panel it becomes a card, its content 16px from every edge */
.prx{padding:var(--dm-s-4) 0;display:flex;flex-direction:column;gap:var(--dm-s-3);container-type:inline-size}
.prx.panel{padding:var(--dm-s-4)}
.prx-h{display:flex;gap:10px;align-items:center}
.prx-ic{width:32px;height:32px;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));background:var(--dm-pp-bg);color:var(--dm-pp);display:grid;place-items:center;flex:none}
.prx-ht{display:flex;flex-direction:column;min-width:0}
.prx-ht b{font-weight:500;font-size:13.5px}
.prx-ht span{font-size:12.5px}
.prx-diff{display:flex;align-items:center;gap:var(--dm-s-2);padding:10px;border-radius:var(--dm-r-in);background:var(--dm-chip);flex-wrap:wrap}
.prx-sw{display:flex;align-items:center;gap:var(--dm-s-2);font-size:12px;flex:1;min-width:0}
.prx-ar{color:var(--dm-muted);display:grid}
/* too narrow for the change on one line (a phone): the new value goes under the old one, the arrow pointing down between
   them under the swatches, so nothing runs out of the box */
@container (max-width:300px){.prx-diff{flex-direction:column;align-items:flex-start;gap:6px}.prx-sw{flex:none}.prx-ar{width:18px;justify-items:center;transform:rotate(90deg)}}
.prx-c{width:18px;height:18px;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));flex:none;box-shadow:inset 0 0 0 1px rgba(0,0,0,.08);transition:background .5s var(--dm-ease)}
.prx-new .num{transition:opacity .3s}
.prx-cf{display:flex;align-items:center;gap:10px;font-size:12.5px}
.prx-seg{display:flex;gap:3px;flex:1}
.prx-seg i{flex:1;height:5px;border-radius:var(--dm-r-tiny,3px);background:var(--dm-line);transition:background .4s}
/* the confidence is a meter, so its parts take the bright mark green (3:1), not the darker text green */
.prx-seg i.on{background:var(--dm-ok-mark)}
.prx-pc{width:34px;text-align:right;color:var(--dm-fg2)}
/* the toggle's chevron sits on the content's edge, its hover box reaching out round it */
.prx-alt-t{display:flex;align-items:center;gap:6px;margin:-4px -8px;padding:4px 8px;border-radius:var(--dm-r-pill);font-size:12.5px;color:var(--dm-fg2);align-self:flex-start;transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.prx-alt-t:hover{background:color-mix(in srgb,var(--dm-fg) 5%,transparent);color:var(--dm-fg)}}
.prx-alt-t svg{transition:transform .4s var(--dm-ease)}
.prx-alt-t.open svg{transform:rotate(90deg)}
/* the other options: each row's fill is the content's width, no wider, and its swatch and value sit on the columns of the
   change above (10px and 36px in) */
/* the folded options keep no room: the fold takes back the card's gap before it, so the footer sits as far under the toggle as
   the card's other parts sit apart, and opened, the options start 16px under the toggle as before */
.prx-alt{margin-top:calc(-1 * var(--dm-s-3))}
.prx-alts{display:flex;flex-direction:column;gap:2px;padding-top:calc(var(--dm-s-1) + var(--dm-s-3))}
.prx-a{display:flex;align-items:center;gap:var(--dm-s-2);padding:7px 10px;border-radius:var(--dm-r-in);font-size:13px;text-align:left;transition:background-color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.prx-a:hover{background:var(--dm-row)}}
.prx-a .d{margin-left:auto;font-size:12px;color:var(--dm-muted)}
/* narrow (a phone): each other option's line goes under its name, the swatch centred beside the two */
@container (max-width:300px){.prx-a{display:grid;grid-template-columns:18px minmax(0,1fr);column-gap:var(--dm-s-2)}.prx-a .prx-c{grid-row:1/3;align-self:center}.prx-a .d{grid-column:2;margin-left:0}}
/* the footer sits under a hairline in Soft and Blueprint (owner, 21 and 22 Nov), 16px under the content and 16px over its
   buttons, as the card's own edges are; Clean's is a foot strip */
.prx-f{display:flex;align-items:center;justify-content:flex-end;gap:6px;margin-top:var(--dm-s-1);padding-top:var(--dm-s-4);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink primary alone presses */
.prx .pill:active{transform:none}
/* accepted: a neutral line with the green tick (owner, 18 Nov), and Undo */
.prx-done{display:flex;align-items:center;gap:var(--dm-s-2);min-width:0;font-size:13px;color:var(--dm-fg);flex:1}
.prx-done>svg{flex:none;color:var(--dm-ok-mark)}
/* Clean (owner, 19 Nov): a round card with its content 16px from every edge and an off-white foot strip, 16px under the
   options, whose buttons sit 8px from the card's edges, round in its 22px corners; once you answer, the strip holds what
   happened (its tick on the content's 16px column, owner 22 Nov) and Undo. The head's tile is the neutral one with a hairline, as every Clean tile */
:root[data-style="clean"] .prx.panel,:root [data-style="clean"] .prx.panel,:root [data-style="clean"].prx.panel{padding:16px 16px 0}
:root[data-style="clean"] .prx-ic,:root [data-style="clean"] .prx-ic,:root [data-style="clean"].prx-ic{background:var(--dm-chip);color:var(--dm-fg2);box-shadow:inset 0 0 0 1px var(--dm-hair)}
:root[data-style="clean"] .prx-ht b,:root [data-style="clean"] .prx-ht b,:root [data-style="clean"].prx-ht b{line-height:20px}
:root[data-style="clean"] .prx-ht span,:root [data-style="clean"] .prx-ht span,:root [data-style="clean"].prx-ht span{line-height:18px}
:root[data-style="clean"] .prx-seg i,:root [data-style="clean"] .prx-seg i,:root [data-style="clean"].prx-seg i{transition:background-color var(--dm-t) var(--dm-ease)}
:root[data-style="clean"] .prx-alt-t svg,:root [data-style="clean"] .prx-alt-t svg,:root [data-style="clean"].prx-alt-t svg{transition:transform var(--dm-t) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .prx-alt-t:hover,:root [data-style="clean"] .prx-alt-t:hover,:root [data-style="clean"].prx-alt-t:hover,:root[data-style="clean"] .prx-a:hover,:root [data-style="clean"] .prx-a:hover,:root [data-style="clean"].prx-a:hover{background:var(--dm-row)}}
:root[data-style="clean"] .prx.panel .prx-f,:root [data-style="clean"] .prx.panel .prx-f,:root [data-style="clean"].prx.panel .prx-f{margin:4px -16px 0;padding:8px 16px;gap:4px;min-height:45px;border-top:1px solid var(--dm-line);background:var(--dm-strip);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
/* (a step of --dm-ok in the vivid green keeps the tick at 3:1 on the off-white strip, as Attachment tray's does) */
:root[data-style="clean"] .prx.panel .prx-done>svg,:root [data-style="clean"] .prx.panel .prx-done>svg,:root [data-style="clean"].prx.panel .prx-done>svg{color:color-mix(in srgb,var(--dm-ok-mark) 80%,var(--dm-ok))}

DM.def('proposal-card', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{wand}', I('wand')).replace('{right}', I('right','xs')).replace('{chev}', I('chev-r','xs'));
  const segs = $$('.prx-seg i', r), pc = $('.prx-pc', r), at = $('.prx-alt-t', r), alt = $('.prx-alt', r), f = $('.prx-f', r);
  const nw = $('.prx-new', r);
  const all = [
    { bg:'#5b6472', hex:'#5B6472', ratio:'5.9 : 1', conf:84, name:'Suggested', d:'Balanced with the primary' },
    { bg:'#475161', hex:'#475161', ratio:'7.4 : 1', conf:62, name:'Darker', d:'Stronger than the primary' },
    { bg:'#116ff8', hex:'#116FF8', ratio:'4.6 : 1', conf:41, name:'Accent outline', d:'Competes with the CTA' }
  ];
  let cur = 0;
  const alts = $('.prx-alts', r);
  function conf(v){ tween(+pc.textContent.replace('%','') || 0, v, 700, x => { pc.textContent = Math.round(x) + '%'; segs.forEach((s, i) => s.classList.toggle('on', x >= (i + 1) * 20 - 10)); }); }
  function list(){ alts.innerHTML = all.map((o, i) => i === cur ? '' : `<button class="prx-a" data-i="${i}"><span class="prx-c" style="background:${o.bg}"></span><span>${o.name}, ${o.ratio}</span><span class="d">${o.d}</span></button>`).join(''); $$('.prx-a', alts).forEach(a => a.onclick = () => apply(+a.dataset.i)); }
  function apply(i){ cur = i; const o = all[i]; $('.prx-c', nw).style.background = o.bg; swap($('.num', nw), o.hex); swap($('.prx-rt', nw), o.ratio); conf(o.conf); list(); stagger($$('.prx-a', alts), 50); }
  at.onclick = () => { const op = alt.classList.toggle('shut'); at.classList.toggle('open', !op); };
  list();
  let saved;
  const reset = () => { f.innerHTML = saved; bind(); };
  function bind(){
    $('.prx-ok', r).onclick = () => { saved = f.innerHTML; alt.classList.add('shut'); at.classList.remove('open');
      f.innerHTML = `<span class="prx-done">${I('ok')}<span>Applied to 3 buttons</span></span><button class="pill ghost sm prx-un">${I('undo','xs')}Undo</button>`; stagger([...f.children], 60);
      $('.prx-un', r).onclick = reset; };
    $('.prx-no', r).onclick = () => { saved = f.innerHTML; f.innerHTML = `<span class="prx-done muted" style="color:var(--dm-muted)">Dismissed. The agent will not suggest this again.</span><button class="pill ghost sm prx-un">Undo</button>`; stagger([...f.children], 60); $('.prx-un', r).onclick = reset; };
  }
  bind(); c.later(400, () => conf(84));
});
